using System;
using System.IO;
using System.Linq;
static class SelfTest {
 static void Assert(bool value,string label){if(!value)throw new Exception("FAIL: "+label);Console.WriteLine("PASS: "+label);}
 internal static void Run(){var root=Path.Combine(Path.GetTempPath(),"GlassFolders-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{Store.Root=root;var a=Path.Combine(root,"Alpha.txt");var b=Path.Combine(root,"Beta.md");var c=Path.Combine(root,"中文文件夹");File.WriteAllText(a,"a");File.WriteAllText(b,"b");Directory.CreateDirectory(c);File.SetLastWriteTimeUtc(a,DateTime.UtcNow.AddDays(-1));var s=new FolderState{Path=root};Assert(Store.Sort(new[]{b,a},s,root)[0]==a,"name order");s.Sort="类型";Assert(Store.Sort(new[]{a,c,b},s,root)[0]==c,"folder type order");s.Sort="修改时间";Assert(Store.Sort(new[]{a,b},s,root)[0]==b,"modification time descending");s.Sort="自定义";s.Orders[root]=new System.Collections.Generic.List<string>{b,a};Assert(Store.Sort(new[]{c,a,b},s,root).SequenceEqual(new[]{b,a,c}),"custom order and newly appended item");var pixels=new byte[256*256*4];for(int y=10;y<42;y++)for(int x=20;x<52;x++)pixels[(y*256+x)*4+3]=255;var bitmap=System.Windows.Media.Imaging.BitmapSource.Create(256,256,96,96,System.Windows.Media.PixelFormats.Bgra32,null,pixels,1024);var cropped=Native.NormalizeIcon(bitmap);Assert(cropped.PixelWidth==32&&cropped.PixelHeight==32,"small icon transparent canvas normalized");Assert(Native.EdgeScrollStep(10,0,300,400)<0&&Native.EdgeScrollStep(10,399,300,400)>0,"drag edge scroll directions");Assert(Native.EdgeScrollStep(10,200,300,400)==0&&Native.EdgeScrollStep(-1,0,300,400)==0,"no scroll at center or outside");Store.Data.Folders.Add(s);Store.Save();Store.Data=new Settings();Store.Load();Assert(Store.Data.Folders.Count==1&&Store.Data.Folders[0].Orders[root][0]==b,"settings round trip");Store.Save();Assert(File.Exists(Path.Combine(root,"settings.json.bak")),"atomic replacement backup");File.WriteAllText(Path.Combine(root,"settings.json"),"invalid");Store.Load();Assert(Store.Data.Folders.Count==0&&Directory.GetFiles(root,"*.invalid-*").Length==1,"corrupt settings preserved");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),"PASS: 10 tests, "+DateTime.Now.ToString("s"));}finally{Directory.Delete(root,true);}}
}
